void aicfb_enable_panel(struct aicfb_info *fbi, u32 on) {
  struct aic_panel *panel = fbi->panel;
  struct panel_desc *desc = fbi->desc;
  struct aic_panel_funcs *funcs;
  struct platform_driver *di = fbi->di;
  struct platform_driver *de = fbi->de;

  funcs = desc ? desc->funcs : panel->funcs;

  pr_info("aicfb_enable_panel: %s\n", on == AICFB_ON ? "ON" : "OFF");

  if (on == AICFB_ON) {
    pr_info("  Panel name: %s\n", panel->name);
    pr_info("  Connector type: %d\n", panel->connector_type);
    if (panel->timings) {
      pr_info("  Timing: %dx%d, pixelclock=%u Hz (%.2f MHz)\n",
              panel->timings->hactive, panel->timings->vactive,
              panel->timings->pixelclock,
              panel->timings->pixelclock / 1000000.0);
    }
    funcs->prepare();
    pr_info("  Calling di->di_funcs->enable()...\n");
    di->di_funcs->enable();
    if (de && de->de_funcs && de->de_funcs->timing_enable) {
      pr_info("  Calling de->de_funcs->timing_enable()...\n");
      de->de_funcs->timing_enable();
    } else {
      pr_warn("  de or de_funcs or timing_enable is NULL, skipping timing "
              "enable\n");
    }
    pr_info("  Calling funcs->enable()...\n");
    funcs->enable(panel);
  } else {
    funcs->disable(panel);
    if (de && de->de_funcs && de->de_funcs->timing_disable) {
      de->de_funcs->timing_disable();
    }
    di->di_funcs->disable();
    funcs->unprepare();
    pr_info("Panel disabled successfully\n");
  }
}

void aicfb_get_panel_info(struct aicfb_info *fbi) {
  struct platform_driver *de = fbi->de;
  struct platform_driver *di = fbi->di;
  struct aic_panel *panel = fbi->panel;
  u32 bpp = 24, dither_en = 1;
  struct panel_desc *desc = NULL;
  unsigned int id;

  if (panel->desc && panel->match_num) {
    id = panel->match_id;
    desc = &panel->desc[id];
    fbi->desc = desc;
  }

  if (di->di_funcs->attach_panel)
    di->di_funcs->attach_panel(panel, desc);

  if (di->di_funcs->get_output_bpp)
    bpp = di->di_funcs->get_output_bpp();

#ifdef CONFIG_AIC_DISABLE_DITHER
  dither_en = 0;
#endif

  if (de->de_funcs->set_mode)
    de->de_funcs->set_mode(panel, desc, bpp, dither_en);
}

